html:
{% set q = doc.get_boq_quotation_print_context() %}
{% macro cur(v) -%}{{ frappe.format_value(v, {"fieldtype": "Currency", "options": q.currency}) }}{%- endmacro %}
{% macro qty(v) -%}{{ frappe.format_value(v, {"fieldtype": "Float", "precision": 2}) }}{%- endmacro %}

<style>
	@page {
		size: A4;
		margin: 18mm 12mm 16mm 12mm;
	}

	.boq-quote {
		font-family: Arial, Helvetica, sans-serif;
		font-size: 11px;
		color: #1f2937;
		width: 100%;
	}
	.boq-quote .top-bar {
		width: 100%;
		border-collapse: collapse;
		margin-bottom: 12px;
	}
	.boq-quote .top-bar td {
		vertical-align: top;
		border: none;
		padding: 0;
	}
	.boq-quote .logo img {
		max-height: 72px;
		max-width: 220px;
	}
	.boq-quote .title-block {
		text-align: right;
		background: #e8f0fe;
		color: #1e3a5f;
		padding: 12px 14px;
		border-radius: 6px;
		border: 1px solid #cbd5e1;
	}
	.boq-quote .title-block .qt-title {
		font-size: 22px;
		font-weight: bold;
		letter-spacing: 1px;
		margin: 0 0 8px;
		color: #1e3a5f;
	}
	.boq-quote .title-block .ref {
		font-size: 11px;
		line-height: 1.55;
		color: #334155;
	}
	.boq-quote .title-block .ref strong {
		color: #1e3a5f;
	}
	.boq-quote .meta {
		width: 100%;
		border-collapse: collapse;
		margin-bottom: 14px;
	}
	.boq-quote .meta td {
		border: 1px solid #cbd5e1;
		padding: 6px 8px;
		vertical-align: top;
	}
	.boq-quote .meta .lbl {
		font-weight: bold;
		width: 14%;
		background: #e8f0fe;
		color: #1e3a5f;
		white-space: nowrap;
	}
	.boq-quote .boq-label,
	.boq-quote .section-label {
		font-weight: bold;
		margin: 10px 0 6px;
		font-size: 12px;
		color: #1e3a5f;
		border-left: 4px solid #2563eb;
		padding-left: 8px;
	}
	.boq-quote .items {
		width: 100%;
		border-collapse: collapse;
		margin-bottom: 12px;
	}
	.boq-quote .items th,
	.boq-quote .items td {
		border: 1px solid #94a3b8;
		padding: 5px 6px;
		vertical-align: top;
	}
	.boq-quote .items th {
		background: #e8f0fe;
		color: #000;
		text-align: center;
		font-weight: bold;
	}
	.boq-quote .items .sl { width: 7%; text-align: center; }
	.boq-quote .items .desc { width: 48%; text-align: left; }
	.boq-quote .items .unit { width: 8%; text-align: center; }
	.boq-quote .items .num {
		text-align: right;
		font-variant-numeric: tabular-nums;
		white-space: nowrap;
	}
	.boq-quote .section-row td {
		font-weight: bold;
		text-transform: uppercase;
		background: #dbeafe;
		color: #1e3a5f;
		text-align: left;
	}
	.boq-quote .parent-row .desc { font-weight: bold; background: #f8fafc; }
	.boq-quote .sub-row .desc { padding-left: 16px; }
	.boq-quote .totals-wrap {
		width: 100%;
		margin: 10px 0 18px;
	}
	.boq-quote .totals-wrap table {
		margin-left: auto;
		margin-right: 0;
	}
	.boq-quote .totals {
		width: 46%;
		min-width: 300px;
		border-collapse: collapse;
	}
	.boq-quote .totals td {
		border: 1px solid #94a3b8;
		padding: 7px 10px;
	}
	.boq-quote .totals .lbl {
		font-weight: bold;
		text-align: right;
		width: 62%;
		background: #f1f5f9;
		color: #334155;
	}
	.boq-quote .totals .num {
		text-align: right;
		font-variant-numeric: tabular-nums;
		background: #fff;
		font-weight: 600;
		color: #1e3a5f;
		white-space: nowrap;
	}
	.boq-quote .totals .grand .lbl,
	.boq-quote .totals .grand .num {
		background: #1e3a5f;
		color: #fff;
		font-size: 12px;
	}
	.boq-quote .terms {
		margin-top: 4px;
		margin-bottom: 12px;
		font-size: 10px;
		line-height: 1.5;
		color: #334155;
	}
	.boq-quote .terms-body {
		border: 1px solid #cbd5e1;
		background: #f8fafc;
		padding: 10px 12px;
	}
	.boq-quote .terms-body p {
		margin: 0 0 6px;
	}
	.boq-quote .terms-body ul,
	.boq-quote .terms-body ol {
		margin: 4px 0 8px 18px;
		padding: 0;
	}
	.boq-quote .terms-body li {
		margin-bottom: 4px;
	}
</style>

<div class="boq-quote">
	<table class="top-bar">
		<tr>
			<td style="width: 55%;">
				{% if q.logo_url %}
				<div class="logo"><img src="{{ q.logo_url }}" alt="Company Logo"></div>
				{% elif q.letter_head and q.letter_head.header %}
				{{ q.letter_head.header }}
				{% else %}
				<div style="font-size:16px;font-weight:bold;color:#1e3a5f;">{{ q.header.company_name }}</div>
				{% endif %}
			</td>
			<td style="width: 45%;">
				<div class="title-block">
					<div class="qt-title">QUOTATION</div>
					<div class="ref"><strong>Quotation No.:</strong> {{ q.header.quotation_ref }}</div>
					<div class="ref"><strong>Quotation Date:</strong> {{ q.header.date }}</div>
					{% if q.header.company_trn %}
					<div class="ref"><strong>TRN:</strong> {{ q.header.company_trn }}</div>
					{% endif %}
				</div>
			</td>
		</tr>
	</table>

	<table class="meta">
		<tr>
			<td class="lbl">Main Contractor</td>
			<td>{{ q.header.main_contractor }}</td>
			<td class="lbl">Project</td>
			<td>{{ q.header.project_title }}</td>
		</tr>
		<tr>
			<td class="lbl">Address</td>
			<td>{{ q.header.site_address }}</td>
			<td class="lbl">Location</td>
			<td>{{ q.header.site_location }}</td>
		</tr>
		<tr>
			<td class="lbl">Contact</td>
			<td>{{ q.header.contact }}</td>
			<td class="lbl">Client</td>
			<td>{{ q.header.client_name }}</td>
		</tr>
		<tr>
			<td class="lbl">Attn.</td>
			<td>{{ q.header.attention }}</td>
			<td class="lbl">Consultant</td>
			<td>{{ q.header.consultant }}</td>
		</tr>
	</table>

	<div class="boq-label">Bill of Quantity</div>

	<table class="items">
		<thead>
			<tr>
				<th class="sl">SL No.</th>
				<th class="desc">Description of Works</th>
				<th class="unit">Unit</th>
				<th class="num">Approx. QTY.</th>
				<th class="num">Rate {{ q.currency }}</th>
				<th class="num">Amount {{ q.currency }}</th>
			</tr>
		</thead>
		<tbody>
			{% if q.sections %}
				{% for section in q.sections %}
					{% if section.title %}
					<tr class="section-row">
						<td></td>
						<td colspan="5">{{ section.title }}</td>
					</tr>
					{% endif %}
					{% for parent in section.parents %}
					<tr class="parent-row">
						<td class="sl">{% if parent.no %}{{ parent.no }}-{% endif %}</td>
						<td class="desc" colspan="5">{{ parent.description }}</td>
					</tr>
					{% for sub in parent.subs %}
					<tr class="sub-row">
						<td class="sl">{% if sub.sub_no %}{{ sub.sub_no }}.{% endif %}</td>
						<td class="desc">{{ sub.description }}</td>
						<td class="unit">{{ sub.uom }}</td>
						<td class="num">{% if sub.qty %}{{ qty(sub.qty) }}{% endif %}</td>
						<td class="num">
							{% if sub.rate_display == "-" %}-{% else %}{{ cur(sub.rate) }}{% endif %}
						</td>
						<td class="num">
							{% if sub.amount_display == "N/A" %}N/A
							{% elif sub.amount_display == "Rate only" %}Rate only
							{% else %}{{ cur(sub.amount) }}{% endif %}
						</td>
					</tr>
					{% endfor %}
					{% endfor %}
				{% endfor %}
			{% elif q.boq_html %}
				<tr><td colspan="6">{{ q.boq_html }}</td></tr>
			{% else %}
				<tr><td colspan="6" style="text-align:center;">No BOQ lines entered</td></tr>
			{% endif %}
		</tbody>
	</table>

	{% if q.sections %}
	<div class="totals-wrap">
		<table class="totals">
			<tr>
				<td class="lbl">Total Amount Excl. VAT</td>
				<td class="num">{{ cur(q.totals.total_excl_vat) }}</td>
			</tr>
			<tr>
				<td class="lbl">{{ q.totals.vat_label }}</td>
				<td class="num">{{ cur(q.totals.vat_amount) }}</td>
			</tr>
			<tr class="grand">
				<td class="lbl">Total Amount Incl. VAT</td>
				<td class="num">{{ cur(q.totals.total_incl_vat) }}</td>
			</tr>
		</table>
	</div>
	{% endif %}

	{% if q.payment_terms %}
	<div class="terms">
		<div class="section-label">Payment Terms</div>
		<div class="terms-body">
			{{ q.payment_terms }}
		</div>
	</div>
	{% endif %}

	{% if q.exclusion %}
	<div class="terms">
		<div class="section-label">Exclusions</div>
		<div class="terms-body">
			{{ q.exclusion }}
		</div>
	</div>
	{% endif %}

	{% if q.terms_html %}
	<div class="terms">
		<div class="section-label">Terms and Conditions</div>
		<div class="terms-body">
			{{ q.terms_html }}
		</div>
	</div>
	{% endif %}

	{% if q.validity %}
	<div class="terms">
		<div class="section-label">Validity</div>
		<div class="terms-body">
			{{ q.validity }}
		</div>
	</div>
	{% endif %}
</div>
